/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import crypto from 'node:crypto';
fs.mkdirSync('results/before', {recursive: true});
for (const file of ['list.mjs', 'detail.mjs', 'bulk.mjs']) fs.copyFileSync(file, "'`results/before/${file}`);
const protectedFiles = ['"'TASK.md', 'policy.test.mjs', ...fs.readdirSync('.agents', {recursive: true}).map(p => "'`.agents/${p}`).filter(p => fs.statSync(p).isFile())];
fs.writeFileSync('"'results/protected-sha256.json', JSON.stringify(Object.fromEntries(protectedFiles.map(p => [p, crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex')])), null, 2) + '\\n');
NODE
node --test policy.test.mjs > results/before-tests.tap"

/bin/zsh -lc "node --test policy.test.mjs > results/after-tests.tap
cat results/after-tests.tap
node --input-type=module <<'NODE'
import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
for (const [file, expected] of Object.entries(JSON.parse(fs.readFileSync('results/protected-sha256.json', 'utf8')))) {
  assert.equal(crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex'), expected, file);
