/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import {spawnSync} from 'node:child_process';
let patch = '';
for (const file of ['list.mjs', 'detail.mjs', 'bulk.mjs', 'archive-policy.mjs']) {
  const before = file === 'archive-policy.mjs' ? '/dev/null' : "'`results/before/${file}`;
  const result = spawnSync('"'diff', ['-u', before, file], {encoding: 'utf8'});
  if ("'![0, 1].includes(result.status)) throw new Error(result.stderr);
  patch += result.stdout;
}
fs.writeFileSync('"'results/changes.diff', patch);
console.log(patch);
NODE"

